using System.Drawing;
using System.Windows.Forms;
using System.Windows.Forms.Design;
public class MyControl : UserControl
{
    public string DisplayName { get; set; } = string.Empty;
    public int MaxItems { get; set; }

    // .NET 9: StatusStrip now defaults to ToolStripRenderMode.Professional
    // instead of System. Set RenderMode explicitly to preserve prior behavior.
    private readonly StatusStrip _statusStrip = new()
    {
        RenderMode = ToolStripRenderMode.System
    };

    public MyControl()
    {
        _statusStrip.Items.Add(new ToolStripStatusLabel("Ready"));
        Controls.Add(_statusStrip);
    }
}

public class DropDownEditor
{
    // .NET 9: DropDownControl now throws ArgumentNullException when passed null.
    // Guard against null before calling.
    public void ShowDropDown(IWindowsFormsEditorService editorService, Control? control)
    {
        if (control is null)
            return;

        editorService.DropDownControl(control);
    }
}

